schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/growth-referral-programs.json",
  "title": "Growth Referral Programs spec",
  "type": "object",
  "required": ["programme_name", "nps_gate", "trigger_event", "qualifying_event", "incentive", "fraud_guard", "k_factor", "attribution", "lifecycle", "disclosure"],
  "additionalProperties": false,
  "definitions": {
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "not_signup": {"not": {"enum": ["signup", "signup_completed", "sign_up", "account_created", "account_creation", "registration_completed", "first_screen_viewed", "welcome_screen_viewed", "onboarding_started"]}},
    "rate": {"type": "number", "minimum": 0, "maximum": 1},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "reward": {
      "type": "object",
      "required": ["kind", "amount", "currency"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["account_credit", "discount", "cash", "free_months"]},
        "amount": {"type": "number", "exclusiveMinimum": 0},
        "currency": {"type": "string", "pattern": "^[A-Z]{3}$"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "programme_name": {"type": "string", "minLength": 3},
    "nps_gate": {
      "type": "object",
      "required": ["metric", "score", "sample_size", "population", "measured_on", "age_days"],
      "additionalProperties": false,
      "properties": {
        "metric": {"type": "string", "enum": ["nps", "willingness_to_recommend"]},
        "score": {"type": "number", "minimum": -100, "maximum": 100},
        "sample_size": {"type": "integer", "minimum": 1},
        "population": {"const": "active_users"},
        "measured_on": {"$ref": "#/definitions/date"},
        "age_days": {"type": "integer", "minimum": 0, "maximum": 90}
      },
      "if": {"properties": {"metric": {"const": "nps"}}},
      "then": {"properties": {"score": {"minimum": 30}}}
    },
    "trigger_event": {
      "type": "object",
      "required": ["name", "reach_share", "instrumented"],
      "additionalProperties": false,
      "properties": {
        "name": {"allOf": [{"$ref": "#/definitions/event_name"}, {"$ref": "#/definitions/not_signup"}]},
        "reach_share": {"$ref": "#/definitions/rate"},
        "instrumented": {"const": true}
      }
    },
    "qualifying_event": {
      "type": "object",
      "required": ["kind", "name", "stated_on_landing_page", "stated_in_every_email"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["first_paid_order", "activation_milestone"]},
        "name": {"allOf": [{"$ref": "#/definitions/event_name"}, {"$ref": "#/definitions/not_signup"}]},
        "minimum_order_value": {"type": "number", "exclusiveMinimum": 0},
        "stated_on_landing_page": {"const": true},
        "stated_in_every_email": {"const": true}
      },
      "if": {"properties": {"kind": {"const": "first_paid_order"}}},
      "then": {"required": ["minimum_order_value"]}
    },
    "incentive": {
      "type": "object",
      "required": ["referrer_reward", "referee_reward", "reward_cost_per_qualified_referee", "blended_paid_cac", "margin_basis", "margin_basis_value", "max_reward_share_of_basis"],
      "additionalProperties": false,
      "properties": {
        "referrer_reward": {"$ref": "#/definitions/reward"},
        "referee_reward": {"$ref": "#/definitions/reward"},
        "reward_cost_per_qualified_referee": {"type": "number", "exclusiveMinimum": 0},
        "blended_paid_cac": {"type": "number", "exclusiveMinimum": 0},
        "margin_basis": {"type": "string", "enum": ["first_order_gross_margin", "expected_ltv"]},
        "margin_basis_value": {"type": "number", "exclusiveMinimum": 0},
        "max_reward_share_of_basis": {"type": "number", "exclusiveMinimum": 0, "maximum": 1}
      }
    },
    "fraud_guard": {
      "type": "object",
      "required": ["referee_must_be_new_account", "one_referral_per_email", "one_referral_per_payment_instrument", "self_referral_signals", "email_normalisation", "reward_hold_days", "reward_hold_covers", "idempotency_key"],
      "additionalProperties": false,
      "properties": {
        "referee_must_be_new_account": {"const": true},
        "one_referral_per_email": {"const": true},
        "one_referral_per_payment_instrument": {"const": true},
        "self_referral_signals": {
          "type": "array",
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["payment_instrument", "device_fingerprint", "ip", "normalised_email"]},
          "allOf": [{"contains": {"const": "payment_instrument"}}, {"contains": {"const": "device_fingerprint"}}, {"contains": {"const": "ip"}}, {"contains": {"const": "normalised_email"}}]
        },
        "email_normalisation": {
          "type": "array",
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["plus_addressing", "dot_variants"]},
          "allOf": [{"contains": {"const": "plus_addressing"}}, {"contains": {"const": "dot_variants"}}]
        },
        "reward_hold_days": {"type": "integer", "minimum": 1},
        "reward_hold_covers": {"type": "string", "enum": ["refund_window", "chargeback_window"]},
        "idempotency_key": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["referrer_id", "referee_id", "qualifying_event"]}
        }
      }
    },
    "k_factor": {
      "type": "object",
      "required": ["invites", "active_referrers", "referee_signups", "invites_per_referrer", "conversion_per_invite", "k", "cycle_time_days", "presented_as", "cac_multiplier", "netted_of_reward_cost"],
      "additionalProperties": false,
      "properties": {
        "invites": {"type": "integer", "minimum": 500},
        "active_referrers": {"type": "integer", "minimum": 50},
        "referee_signups": {"type": "integer", "minimum": 0},
        "invites_per_referrer": {"type": "number", "minimum": 0},
        "conversion_per_invite": {"$ref": "#/definitions/rate"},
        "k": {"type": "number", "minimum": 0},
        "cycle_time_days": {"type": "number", "exclusiveMinimum": 0},
        "presented_as": {"type": "string", "enum": ["cac_multiplier", "viral_growth"]},
        "cac_multiplier": {"type": "number", "minimum": 1},
        "netted_of_reward_cost": {"const": true}
      },
      "if": {"properties": {"k": {"exclusiveMaximum": 1}}},
      "then": {"properties": {"presented_as": {"const": "cac_multiplier"}}}
    },
    "attribution": {
      "type": "object",
      "required": ["per_user_code", "landing_page_accepts_param", "email_accepts_param", "capture_methods", "persisted_server_side_at", "utm_only"],
      "additionalProperties": false,
      "properties": {
        "per_user_code": {"const": true},
        "landing_page_accepts_param": {"const": true},
        "email_accepts_param": {"const": true},
        "capture_methods": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["url_parameter", "first_party_cookie", "code_at_signup"]}
        },
        "persisted_server_side_at": {"const": "referee_account_creation"},
        "utm_only": {"const": false}
      }
    },
    "lifecycle": {
      "type": "object",
      "required": ["announcement", "reminder", "confirmation", "promises_reward_before_qualifying_event"],
      "additionalProperties": false,
      "properties": {
        "announcement": {
          "type": "object",
          "required": ["send_on"],
          "additionalProperties": false,
          "properties": {"send_on": {"$ref": "#/definitions/event_name"}}
        },
        "reminder": {
          "type": "object",
          "required": ["after_days", "audience", "max_sends"],
          "additionalProperties": false,
          "properties": {
            "after_days": {"type": "integer", "minimum": 1},
            "audience": {"const": "zero_referrals"},
            "max_sends": {"const": 1}
          }
        },
        "confirmation": {
          "type": "object",
          "required": ["send_on", "recipients"],
          "additionalProperties": false,
          "properties": {
            "send_on": {"const": "qualifying_event"},
            "recipients": {
              "type": "array",
              "uniqueItems": true,
              "items": {"type": "string", "enum": ["referrer", "referee"]},
              "allOf": [{"contains": {"const": "referrer"}}, {"contains": {"const": "referee"}}]
            }
          }
        },
        "promises_reward_before_qualifying_event": {"const": false}
      }
    },
    "disclosure": {
      "type": "object",
      "required": ["reward_disclosed_on_shared_content", "terms_url", "terms_cover", "earnings_claims"],
      "additionalProperties": false,
      "properties": {
        "reward_disclosed_on_shared_content": {"const": true},
        "terms_url": {"type": "string", "pattern": "^https?://"},
        "terms_cover": {
          "type": "array",
          "minItems": 4,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["qualifying_event", "reward_timing", "exclusions", "fraud_reversal"]}
        },
        "earnings_claims": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["claim", "period", "verified"],
            "additionalProperties": false,
            "properties": {
              "claim": {"type": "string", "minLength": 5},
              "period": {"type": "string", "minLength": 4},
              "verified": {"const": true}
            }
          }
        }
      }
    }
  }
}
